19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	};
25	
26	const quotePremium = (items: Item[]): number => {
27	  const base = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
28	  return base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
29	};
30	
31	export const runScenario = (scenario: Scenario): ScenarioResults => {
32	  return {
33	    results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
34	  };
35	};
