const ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

const quotePremium = (items: Item[]): number => {
  const policyBasePremium = items.reduce(
    (sum, item) => sum + ITEM_BASE_PREMIUMS[item.type],
    0,
  );
  return policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
};
